<?php
use App\Http\Controllers\Academic\{AttendanceController,GradeController,ReportController};use Illuminate\Support\Facades\Route;
Route::middleware(['auth','active','force-password-change'])->prefix('academic')->name('academic.')->group(function(){Route::get('attendance',[AttendanceController::class,'index'])->middleware('permission:academic-attendance.view')->name('attendance.index');Route::post('attendance',[AttendanceController::class,'store'])->name('attendance.store');Route::get('attendance/history',[AttendanceController::class,'history'])->middleware('permission:academic-attendance.view')->name('attendance.history');Route::get('grades',[GradeController::class,'index'])->middleware('permission:academic-grades.view')->name('grades.index');Route::post('grades',[GradeController::class,'store'])->name('grades.store');Route::post('grades/subjects',[GradeController::class,'subject'])->name('grades.subjects.store');Route::get('reports',ReportController::class)->middleware('permission:academic-reports.view')->name('reports.index');});
